files.content:
:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --accent: #f5a623;
  --text: #e8e8f0;
  --muted: #9a9ab0;
  --die-bg: #f0f0f8;
  --die-pip: #1e1e2e;
  --focus: #f5a623;
  font-size: 18px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  padding: 1rem;
}

.card {
  background: var(--card);
  border-radius: 20px;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  letter-spacing: 1px;
  color: var(--accent);
}

h2 {
  font-size: 1.1rem;
  color: var(--muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 0.5rem;
}

fieldset {
  border: none;
}

legend {
  font-size: 1rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
  display: block;
}

.radio-group {
  display: flex;
  gap: 0.75rem;
}

.radio-label {
  flex: 1;
  position: relative;
  cursor: pointer;
}

.radio-label input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
}

.radio-label span {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  background: var(--bg);
  border: 2px solid transparent;
  border-radius: 12px;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text);
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.radio-label:hover span {
  background: #3a3a50;
}

.radio-label input:checked + span {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

.radio-label input:focus-visible + span {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.roll-btn {
  min-height: 56px;
  background: var(--accent);
  color: var(--bg);
  border: none;
  border-radius: 14px;
  font-size: 1.3rem;
  font-weight: 800;
  letter-spacing: 1px;
  cursor: pointer;
  transition: transform 0.1s, background 0.15s, box-shadow 0.15s;
  box-shadow: 0 4px 0 #b87a10;
}

.roll-btn:hover {
  background: #ffb733;
}

.roll-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.roll-btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #b87a10;
}

.dice-area {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  min-height: 100px;
  align-items: center;
}

.placeholder {
  color: var(--muted);
  font-style: italic;
}

.die {
  width: 80px;
  height: 80px;
  background: var(--die-bg);
  border-radius: 14px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  padding: 10px;
  gap: 4px;
  box-shadow: inset 0 -4px 0 rgba(0, 0, 0, 0.15), 0 4px 8px rgba(0, 0, 0, 0.3);
  animation: pop 0.25s ease-out;
}

@keyframes pop {
  0% { transform: scale(0.6); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.pip {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--die-pip);
  opacity: 0;
}

.pip.on {
  opacity: 1;
}

.total {
  text-align: center;
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--accent);
  min-height: 1.6em;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  font-size: 1rem;
  color: var(--text);
}

.history-list li {
  background: var(--bg);
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  animation: slide 0.2s ease-out;
}

@keyframes slide {
  from { transform: translateX(-10px); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

.history-list .faces {
  color: var(--muted);
  letter-spacing: 2px;
}

.history-list .sum {
  font-weight: 700;
  color: var(--accent);
}

@media (max-width: 400px) {
  :root { font-size: 16px; }
  .card { padding: 1.5rem 1rem; }
  .die { width: 64px; height: 64px; padding: 8px; gap: 3px; }
  .radio-label span { min-height: 44px; }
  .roll-btn { min-height: 50px; font-size: 1.15rem; }
}

(function () {
  'use strict';

  // Pip positions for each face (1-6) on a 3x3 grid (indices 0-8).
  var FACES = {
    1: [4],
    2: [0, 8],
    3: [0, 4, 8],
    4: [0, 2, 6, 8],
    5: [0, 2, 4, 6, 8],
    6: [0, 2, 3, 5, 6, 8]
  };

  var diceArea = document.getElementById('dice-area');
  var totalEl = document.getElementById('total');
  var historyList = document.getElementById('history-list');
  var rollBtn = document.getElementById('roll-btn');
  var countRadios = document.querySelectorAll('input[name="dice-count"]');

  var history = [];
  var MAX_HISTORY = 5;

  function getDiceCount() {
    for (var i = 0; i < countRadios.length; i++) {
      if (countRadios[i].checked) return parseInt(countRadios[i].value, 10);
    }
    return 1;
  }

  function rollDie() {
    return Math.floor(Math.random() * 6) + 1;
  }

  function createDie(value) {
    var die = document.createElement('div');
    die.className = 'die';
    die.setAttribute('role', 'img');
    die.setAttribute('aria-label', 'Die showing ' + value);

    for (var i = 0; i < 9; i++) {
      var pip = document.createElement('div');
      pip.className = 'pip';
      if (FACES[value].indexOf(i) !== -1) {
        pip.classList.add('on');
      }
      die.appendChild(pip);
    }
    return die;
  }

  function renderDice(results) {
    diceArea.innerHTML = '';
    for (var i = 0; i < results.length; i++) {
      diceArea.appendChild(createDie(results[i]));
    }
  }

  function renderHistory() {
    historyList.innerHTML = '';
    for (var i = 0; i < history.length; i++) {
      var entry = history[i];
      var li = document.createElement('li');

      var faces = document.createElement('span');
      faces.className = 'faces';
      faces.textContent = entry.results.join(' · ');

      var sum = document.createElement('span');
      sum.className = 'sum';
      sum.textContent = '= ' + entry.total;

      li.appendChild(faces);
      li.appendChild(sum);
      historyList.appendChild(li);
    }
  }

  function roll() {
    var count = getDiceCount();
    var results = [];
    var total = 0;

    for (var i = 0; i < count; i++) {
      var value = rollDie();
      results.push(value);
      total += value;
    }

    renderDice(results);
    totalEl.textContent = 'Total: ' + total;

    history.unshift({ results: results, total: total });
    if (history.length > MAX_HISTORY) {
      history.pop();
    }
    renderHistory();
  }

  rollBtn.addEventListener('click', roll);
})();
